new={}; moved=0; kept=[]
for k,v in st.items():
    if v.get('unit')==U and norm(v['name']) in MAP:
        t,n=MAP[norm(v['name'])]; v=dict(v,turma=t,name=n); k2=skey(U,t,n); moved+=1
        if k2 in new and (new[k2].get('updatedAt','')>v.get('updatedAt','')): continue
        new[k2]=v
    else:
        if v.get('unit')==U: kept.append(v['name']+' / '+v['turma'])
        new[k]=v
print('students: total',len(st),'->',len(new),'| coc-lauro migrados',moved,'| coc-lauro mantidos',kept)
print('  coc-lauro por turma:',dict(collections.Counter(v['turma'] for v in new.values() if v.get('unit')==U)))
# 2) salas por série
salas=collections.defaultdict(set)
for t,n in MAP.values(): salas[t.rsplit(' ',1)[0]].add(t)
# 3) teachers: série com sala única herda o(a) professor(a); chaves antigas mantidas
for serie,ts in salas.items():
    old=te.get(f'{U}|{serie}')
    if old and len(ts)==1:
        k=f'{U}|{next(iter(ts))}'
        if not te.get(k): te[k]=old; print('  teacher',k,'=',old)
# 4) professors: cada série vira todas as salas dessa série (mantém a antiga se ainda há alunos nela)
for p in pr:
    if p.get('unit')!=U: continue
    novo=[]
    for t in p.get('turmas',[]):
        if t in salas:
            novo+=sorted(salas[t])
            if t in EXTRA_TURMAS: novo.append(t)
        else: novo.append(t)
    print('  prof',p.get('name'),p.get('turmas'),'->',novo); p['turmas']=novo
if DRY: print('DRY RUN — nada gravado'); sys.exit()
for f,o in (('students.json',new),('teachers.json',te),('professors.json',pr)):
    tmp=f'{D}/{f}.tmp'; json.dump(o,open(tmp,'w'),ensure_ascii=False,indent=2); os.replace(tmp,f'{D}/{f}')
print('GRAVADO')
